package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;

/** Original native resolutions and fictional retained outcomes; final composition performs no SQL. */
class SourceValuePartialFinalResultTest {
    SourceValueResolvedStageResultTest q;SourceValuePartialResolutionTest f;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup(boolean mixed)throws Exception{q=new SourceValueResolvedStageResultTest(){@Override GenerationJdbcStoreTest database(){return SourceValuePartialFinalResultTest.this.database();}};q.setup(mixed);f=q.f;}
    SourceValueFinalResult result(SourceValueStageResult whole){return SourceValueFinalResult.createPartial(f.f.plan,f.outcomes.original,whole);}
    @Test void SparseAppliedValuesKeepOriginalOmissionsAndSelectOnlyOriginalSuccesses()throws Exception{
        setup(true);q.prepare();f.outcomes.pure=new SourceValueStageResultTest(){@Override ObjectNode payload(SourcePartitionPlanner.Chunk c){var n=super.payload(c);n.put("summary","Fictional partial source summary tail-"+c.stagePart());var selected=n.putArray("selected_item_ids");int count=0;for(var row:n.get("items")){((ObjectNode)row).put("high_value",true);if(count++<5)selected.add(row.get("item_id").asText());}return n;}};int last=f.f.plan.chunks().size()-1;for(int n=0;n<last;n++)q.terminal(n,"failed");f.outcomes.complete(last);var whole=SourceValueStageResult.createResolved(f.read());int rows=f.db.count("1=1"),calls=f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);var result=result(whole);var value=CanonicalJson.parse(result.json());var nativeValue=CanonicalJson.parse(whole.json());assertEquals("source-value-final-result-v2",value.get("schema_version").asText());assertEquals(200,value.get("eligible_count").asInt());assertEquals(whole.members().size(),value.get("applied_member_count").asInt());assertEquals(200-whole.members().size(),value.get("unapplied_member_count").asInt());assertEquals(f.f.plan.chunks().size(),value.get("stage_part_count").asInt());assertEquals(1,value.get("fragment_count").asInt());assertEquals(5,result.selected().size());assertEquals(5,result.selected().stream().map(SourceValueFinalResult.Selected::entityId).distinct().count());assertTrue(result.selected().stream().allMatch(s->s.rootId().equals(f.f.plan.chunks().getLast().rootId())));assertTrue(result.summary().contains("tail-"+last));assertTrue(result.missing().stream().anyMatch(m->m.reason().equals("dedup_failed")));assertEquals(last,result.missing().stream().filter(m->m.reason().equals("value_failed")).count());assertFalse(result.missing().stream().anyMatch(m->m.reason().equals("collection_partial")));assertEquals(nativeValue.get("missing"),value.get("missing"));assertEquals(whole.hash(),value.get("whole_result_hash").asText());assertEquals(CanonicalJson.hash(CanonicalJson.Domain.CONTENT,value),result.hash());assertEquals(result.json(),result(whole).json());assertEquals(rows,f.db.count("1=1"));assertEquals(calls,f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertThrows(UnsupportedOperationException.class,()->result.missing().clear());assertThrows(RuntimeException.class,()->SourceValueFinalResult.create(f.f.plan,f.outcomes.original,whole));
    }
    @Test void EveryFailedValueKeepsPlannedCountsAndDoesNotClaimNoInput()throws Exception{
        setup(true);q.prepare();for(int n=0;n<f.f.plan.chunks().size();n++)q.terminal(n,"cancelled");var whole=SourceValueStageResult.createResolved(f.read());var result=result(whole);var value=CanonicalJson.parse(result.json());assertEquals(200,value.get("eligible_count").asInt());assertEquals(0,value.get("applied_member_count").asInt());assertEquals(200,value.get("unapplied_member_count").asInt());assertEquals(0,value.get("valuable_count").asInt());assertEquals(0,value.get("fragment_count").asInt());assertTrue(result.selected().isEmpty());assertTrue(result.summary().contains("原计划包含 200 条"));assertFalse(result.summary().contains("没有可分析输入"));assertEquals(f.f.plan.chunks().size(),result.missing().stream().filter(m->m.reason().equals("value_cancelled")).count());assertEquals("partial",result.coverageState());
    }
    @Test void FailedDedupZeroValueRetainsAcceptedInputAndItsActualFailureReason()throws Exception{
        setup(false);var whole=SourceValueStageResult.createResolved(f.read());int rows=f.db.count("1=1");var result=result(whole);assertEquals(1,f.outcomes.original.accepted());assertEquals(0,CanonicalJson.parse(result.json()).get("eligible_count").asInt());assertEquals(1,result.missing().size());assertEquals("dedup_failed",result.missing().getFirst().reason());assertTrue(result.summary().contains("原始去重证明"));assertFalse(result.summary().contains("没有可分析输入"));assertEquals(rows,f.db.count("1=1"));
    }
    @Test void ExplicitRoutesOriginalIdentityAndCapacityRemainClosed()throws Exception{
        setup(false);var whole=SourceValueStageResult.createResolved(f.read());assertThrows(GenerationFlowService.CapacityGuarded.class,()->SourceValueFinalResult.createPartialWithinCapacity(f.f.plan,f.outcomes.original,whole,64));assertThrows(RuntimeException.class,()->SourceValueFinalResult.createPartialWithinCapacity(f.f.plan,f.outcomes.original,whole,0));assertThrows(RuntimeException.class,()->SourceValueFinalResult.createPartial(null,f.outcomes.original,whole));var old=new SourceValueFinalResultTest().fixture(0,false,false,false,"","",List.of());assertThrows(RuntimeException.class,()->SourceValueFinalResult.createPartial(old.plan(),old.universe(),old.whole()));assertEquals("source-value-final-result-v1",CanonicalJson.parse(SourceValueFinalResult.create(old.plan(),old.universe(),old.whole()).json()).get("schema_version").asText());assertThrows(RuntimeException.class,()->SourceValueFinalResult.createPartial(old.plan(),old.universe(),whole));
    }
}
